"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["86864"],{43562(e){e.exports=JSON.parse('{"id":"V4-223","slug":"tokenomics","term":"Tokenomics","also_known_as":[],"difficulty":"Advanced","definition":"Tokenomics is the design and economics of a cryptocurrency or digital token, including how tokens are created, distributed, used and removed from circulation, and how these features affect their value and the incentives of participants.","explanation":["The word combines token and economics. Tokenomics covers questions such as how many tokens exist and whether there is a maximum supply; how new tokens are issued, such as through mining or staking rewards; how tokens are distributed among founders, investors, the community and treasury; vesting schedules, which limit when insiders can sell; and what the tokens are used for.","Some tokens have mechanisms that reduce supply, such as burning, where tokens are permanently removed from circulation, often using a share of transaction fees.","For example, Bitcoin\u2019s tokenomics include a fixed maximum supply of 21 million coins and a halving of new issuance roughly every four years.","Investors examine tokenomics to judge whether a token\u2019s design supports long-term value. Warning signs include large allocations to founders and early investors with short vesting periods, which could lead to heavy selling, unlimited supply growth or unclear uses for the token. Good tokenomics alone does not guarantee success; a token\u2019s value ultimately depends on demand for the network or service it supports."],"note":"","total":1725,"prev":{"slug":"tokenization","term":"Tokenization"},"next":{"slug":"too-big-to-fail","term":"Too Big to Fail"}}')}}]);